local BobbinMaker = {}
local PRODUCTS = {
    simple_wood_bobbin = { name = "Preprosta lesena navojnica", woodCost = 2, time = 3, cost = 40, science = 15, happiness = 1, description = "Preprosta lesena navojnica za navijanje niti." },
    iron_banded_bobbin = { name = "Železnopasna navojnica", woodCost = 2, ironCost = 1, time = 5, cost = 110, science = 28, happiness = 1, prestige = 2, description = "Železnopasna navojnica za trgovce." },
    silver_trimmed_bobbin = { name = "Srebrnoobrobljena navojnica", woodCost = 2, silverCost = 1, ironCost = 1, time = 8, cost = 280, science = 42, happiness = 2, prestige = 6, description = "Srebrnoobrobljena navojnica za plemiče." },
    gold_trimmed_bobbin = { name = "Zlatookrasna navojnica", woodCost = 2, goldCost = 1, silverCost = 1, ironCost = 1, time = 12, cost = 680, science = 56, happiness = 3, prestige = 14, description = "Zlatookrasna navojnica za visoke plemiče." },
    jewel_set_bobbin = { name = "Draguljasta navojnica", woodCost = 2, goldCost = 1, silverCost = 1, ironCost = 1, jewelCost = 1, time = 16, cost = 1500, science = 72, happiness = 5, prestige = 27, description = "Navojnica z draguljem za visoko plemstvo." },
    royal_grand_bobbin = { name = "Kraljevski veliki navojnica", woodCost = 3, goldCost = 2, silverCost = 2, ironCost = 1, jewelCost = 2, pearlCost = 2, time = 23, cost = 3300, science = 92, happiness = 12, prestige = 58, description = "Velika kraljevska navojnica z biseri in zlatom za kronanje." },
}
local BUILDINGS = {
    bobbin_workshop = { name = "Navojnična delavnica", cost = { gold = 260, wood = 140, stone = 120 }, upkeep = 6, qualityBonus = 5 },
    textile_loft = { name = "Tekstilna podstrešje", cost = { gold = 950, wood = 280, stone = 240, silver = 6, iron = 6 }, upkeep = 22, qualityBonus = 18 },
    master_bobbin_atelier = { name = "Mojstrski navojnični atelje", cost = { gold = 2700, wood = 380, stone = 480, silver = 32, gold = 6 }, upkeep = 62, qualityBonus = 30 },
    royal_textile_palace = { name = "Kraljevska tekstilna palača", cost = { gold = 11500, wood = 580, stone = 760, gold = 75, jewel = 18 }, upkeep = 230, qualityBonus = 55, prestigeBonus = 50 },
}
BobbinMaker.woodStock = 16; BobbinMaker.ironStock = 10; BobbinMaker.silverStock = 6; BobbinMaker.goldStock = 6; BobbinMaker.jewelStock = 4; BobbinMaker.pearlStock = 4
BobbinMaker.productStock = {}; BobbinMaker.buildings = {}; BobbinMaker.maker = nil; BobbinMaker.activeMaking = {}; BobbinMaker.totalProducts = 0; BobbinMaker.dayTimer = 0
function BobbinMaker.init() BobbinMaker.woodStock=16; BobbinMaker.ironStock=10; BobbinMaker.silverStock=6; BobbinMaker.goldStock=6; BobbinMaker.jewelStock=4; BobbinMaker.pearlStock=4; BobbinMaker.productStock={}; BobbinMaker.buildings={}; BobbinMaker.maker=nil; BobbinMaker.activeMaking={}; BobbinMaker.totalProducts=0; BobbinMaker.dayTimer=0; print("[BobbinMaker] Royal Bobbin Maker System initialized (6 products, 4 buildings)") end
function BobbinMaker.hireMaker(n,s) s=s or math.random(55,90); local c=540+s*12; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; BobbinMaker.maker={name=n or ("Navojničar "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Navojničar najet: %s (spretnost: %d)",BobbinMaker.maker.name,s),"success") end; return true end
function BobbinMaker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function BobbinMaker.build(id) local ok,e=BobbinMaker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(BobbinMaker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function BobbinMaker.getQualityBonus() local b=0; for _,bd in ipairs(BobbinMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function BobbinMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.woodCost and BobbinMaker.woodStock<(d.woodCost or 0) then return false,"Premalo lesa" end; if d.ironCost and BobbinMaker.ironStock<(d.ironCost or 0) then return false,"Premalo železa" end; if d.silverCost and BobbinMaker.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and BobbinMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and BobbinMaker.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if d.pearlCost and BobbinMaker.pearlStock<(d.pearlCost or 0) then return false,"Premalo biserov" end; if #BobbinMaker.buildings==0 then return false,"Potrebna navojnična delavnica" end; if not BobbinMaker.maker then return false,"Potreben navojničar" end; return true end
function BobbinMaker.make(pt,qty) qty=qty or 1; local ok,e=BobbinMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.woodCost then BobbinMaker.woodStock=BobbinMaker.woodStock-d.woodCost*qty end; if d.ironCost then BobbinMaker.ironStock=BobbinMaker.ironStock-d.ironCost*qty end; if d.silverCost then BobbinMaker.silverStock=BobbinMaker.silverStock-d.silverCost*qty end; if d.goldCost then BobbinMaker.goldStock=BobbinMaker.goldStock-d.goldCost*qty end; if d.jewelCost then BobbinMaker.jewelStock=BobbinMaker.jewelStock-d.jewelCost*qty end; if d.pearlCost then BobbinMaker.pearlStock=BobbinMaker.pearlStock-d.pearlCost*qty end; local t=d.time; if BobbinMaker.maker then t=math.max(1,t-math.floor(BobbinMaker.maker.skill/13)) end; table.insert(BobbinMaker.activeMaking,{id="bobbin_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,science=d.science or 0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function BobbinMaker.completeMaking(m) local q=1.0+(BobbinMaker.getQualityBonus()/100); if BobbinMaker.maker then q=q+(BobbinMaker.maker.skill/140) end; q=math.min(2.5,q); BobbinMaker.productStock[m.productType]=(BobbinMaker.productStock[m.productType] or 0)+m.quantity; BobbinMaker.totalProducts=BobbinMaker.totalProducts+m.quantity; if m.science>0 and _G.state then _G.state.science=(_G.state.science or 0)+m.science end; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if BobbinMaker.maker then BobbinMaker.maker.itemsMade=BobbinMaker.maker.itemsMade+m.quantity; if math.random()<0.25 then BobbinMaker.maker.skill=math.min(100,BobbinMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Navojnica izdelana: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"bobbin.completed",{productName=m.productName,science=m.science,prestige=m.prestige,happiness=m.happiness}) end end
function BobbinMaker.update(dt) if not _G.state then return end; BobbinMaker.dayTimer=BobbinMaker.dayTimer+dt; if BobbinMaker.dayTimer>=30 then BobbinMaker.dayTimer=0; for i=#BobbinMaker.activeMaking,1,-1 do local m=BobbinMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then BobbinMaker.completeMaking(m); table.remove(BobbinMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(BobbinMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if BobbinMaker.maker then tu=tu+14 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function BobbinMaker.getStats() return {woodStock=BobbinMaker.woodStock,ironStock=BobbinMaker.ironStock,silverStock=BobbinMaker.silverStock,goldStock=BobbinMaker.goldStock,jewelStock=BobbinMaker.jewelStock,pearlStock=BobbinMaker.pearlStock,productStock=BobbinMaker.productStock,numBuildings=#BobbinMaker.buildings,hasMaker=BobbinMaker.maker~=nil,makerName=BobbinMaker.maker and BobbinMaker.maker.name or "—",makerSkill=BobbinMaker.maker and BobbinMaker.maker.skill or 0,activeMaking=#BobbinMaker.activeMaking,totalProducts=BobbinMaker.totalProducts} end
return BobbinMaker
